from decimal import Decimal, ROUND_HALF_UP


def to_cents(text):
    """Parse a decimal amount string into integer cents."""
    text = text.strip()
    d = Decimal(text)
    # Round half away from zero: use sign * abs().quantize(ROUND_HALF_UP)
    if d >= 0:
        return int(d.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    else:
        return -int((-d).quantize(Decimal('1'), rounding=ROUND_HALF_UP))


def split(total_cents, n):
    """Split an amount into n near-equal parts."""
    if n < 1:
        raise ValueError("n must be >= 1")
    quotient = total_cents // n
    remainder = total_cents % n
    # larger absolute value parts first
    result = []
    for i in range(remainder):
        result.append(quotient + 1)
    for i in range(n - remainder):
        result.append(quotient)
    return result


def allocate(total_cents, weights):
    """Split an amount in proportion to weights."""
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    total_w = sum(weights)
    if total_w == 0:
        raise ValueError("weights must sum to > 0")

    n = len(weights)
    # exact share as Decimal
    shares = [Decimal(total_cents) * w / total_w for w in weights]
    # truncated toward zero
    floored = [int(s // 1 if s >= 0 else (s - 1).to_integral_value()) for s in shares]
    # remaining cents to distribute
    distributed = sum(floored)
    remaining = total_cents - distributed

    # fractional parts and their original indices; largest frac wins, tie -> lower index
    fracs = [(shares[i] - Decimal(int(shares[i])) if shares[i] >= 0 else (shares[i] - int(shares[i])), i) for i in range(n)]
    fracs.sort(key=lambda x: (-x[0], x[1]))

    result = list(floored)
    for k in range(remaining):
        idx = fracs[k][1]
        if total_cents >= 0:
            result[idx] += 1
        else:
            result[idx] -= 1
    return result
