    for s in shares:
        if s >= 0:
            floored.append(int(s // 1))
        else:
            # int() truncates toward zero in Python
            floored.append(int(s))

    # Determine which positions need adjustment
    # For positive total_cents: share is like 3.5, floored is 3, need +1 for larger fractions
    # For negative total_cents: share is like -3.5, floored is -3, need -1 for larger fractions
    if total_cents >= 0:
        fracs = [(shares[i] - Decimal(floored[i]), i) for i in range(n)]
